/** 
 * The redirection triggered by the OAuth authentication server as response to the GET AUTHORIZATION request is caught here. To make this possible, this activity needs to be qualified with android:launchMode = "singleTask" in the AndroidManifest.xml file.
 */
@Override protected void onNewIntent(Intent intent){
  Log_OC.d(TAG,"onNewIntent()");
  Uri data=intent.getData();
  if (data != null && data.toString().startsWith(getString(R.string.oauth2_redirect_uri))) {
    mNewCapturedUriFromOAuth2Redirection=data;
  }
}
